 n=source['number']
 assert set(row)==required,n
 for k in ['code_id','source_id','source_sha256','number']: assert row[k]==source[k],(n,k)
 assert row['status']=='rewrite_draft',n
 assert row['reason'] and row['review_notes'],n
 p=row['proposed_xml']
 assert isinstance(p,str) and p.strip(),n
 assert text_of(p)"'!=text_of(source['"'source_xml']),n
 assert not re.search(r'https?://|"'```|texte inchangé|à compléter|'"\\[\\.\\.\\.\\]',p,re.I),n
 root=E.fromstring('<root>'+p+'</root>')
 for el in root.iter():
  if el is root: continue
  assert el.tag in allowed,(n,el.tag)
  assert all(k in ('rowspan','colspan') and re.fullmatch(r'[0-9]+',v) for k,v in el.attrib.items()),(n,el.attrib)
 for tag in ['p','table','thead','tbody','tfoot','tr','th','td']:
  assert len(re.findall(r'<'+tag+r'\\b',source['source_xml']))==len(root.findall('.//'+tag)),(n,tag)
 assert labels(source['source_xml'])==labels(p),(n,'subdivisions')
 assert not numbers(source['source_xml'])-numbers(p),(n,'chiffres supprimés')
 if n"'!='"'L153-2': assert numbers(source['source_xml'])==numbers(p),(n,'chiffres ajoutés')
 else: assert not numbers(p)-(numbers(source['source_xml'])+numbers(source['source_notes_xml'])),(n,'chiffres non sourcés')
 # Each nonempty block separated by a paragraph or line break stays in its ordinal position.
 def blocks(x):
  return [z for z in re.split(r'</p>|<br\\s*/?>',x) if re.sub(r'<["'^>]*>'"','',z).strip()]
 assert len(blocks(source['source_xml']))==len(blocks(p)),(n,'alinéas')
 # Explicit numerical words for key limits and safeguards.
 for word in ['six','vingt','trois','cinq','moitié']:
  if re.search(r'\\b'+word+r'\\b',text_of(source['source_xml'])):
   assert re.search(r'\\b'+word+r'\\b',text_of(p)),(n,word)
print('VALIDÉ : 24 objets ; identifiants exacts ; 24 textes intégraux distincts des sources ; statut rewrite_draft.')
print('VALIDÉ : XML autorisé ; ordre des subdivisions et nombre d’alinéas conservés ; aucun nombre source perdu ; aucune structure de tableau perdue.')
print('L153-2 : les seuls nombres ajoutés proviennent de sa note source historique.')
